PAYLOAD='{"upd": {"loot_progression|34": "Use Renown Rank, facility/service progression, region, unlocks, recipes, and materials, not LUK.", "loot_progression|44": "Legendary may drop from any normal encounter at very low chance, but Item Level is restricted by Map Level. Renown Rank does not directly decide drop rarity.", "loot_progression|74": "Renown is earned from successful quests only. Renown per successful quest: Normal 100, Hard 130, Boss 200, Exploration 250 (paid once after the 3rd win of the run). Normal battles, elites, bosses, dispatch and bonus objectives give no Renown unless they are the quest\'s own completion. Not per enemy kill. Failure costs: −300 / −390 / −600 / −750 (loot_progression 90).", "loot_progression|75": "Renown replaces Guild Level and Guild XP everywhere; there is only one account progression. Its steps are called Ranks, not levels. Renown Rank sets quest / enemy level (loot_progression 87), the Blacksmith cap (guild_facilities 12/41/50), roster size (loot_progression 91) and recruit level: recruits appear around Rank − 5 to Rank. Buildings still cost gold only.", "loot_progression|80": "Anti-farming: the same distance bands as unit XP, using min(Rank, 99) minus the quest level: gap <=5 full Renown; 6-10 ×0.75; 11-15 ×0.50; 16-20 ×0.25; 21+ ×0.10. A quest above your Rank gives no extra Renown. Above Rank 99 see loot_progression 88.", "loot_progression|82": "Renown to the next Rank = 250 + Rank × 5. Examples: Rank 1→2 = 255; Rank 50→51 = 500; Rank 98→99 = 740. Pace (Simulator v2, 3× penalty, required fix applied): Rank 99 takes about 540–630 battles at 5–10% quest losses, and about 785–925 at 20%. Rank 150 takes about 1,136 battles and Rank 200 about 1,936 (at 10% loss). At 40% losses: about 2,475 battles to Rank 99, with stalls of 96–180 battles. Rank never drops.", "loot_progression|83": "No Rank cap. Rank keeps going past 99, so higher content can be added later (loot_progression 89).", "unit_progression|79": "Trivial content provides sharply reduced XP via overleveled penalty. Same direction as Renown anti-farming.", "unit_progression|82": "Unit XP and Renown are separate. Renown = account progression; it comes from successful quests only and drives quest level, Blacksmith cap and roster size. Unit XP = per-unit stat progression. Separate formulas.", "unit_progression|85": "Leveling is one of many parallel systems: Renown, equipment rarity, loadout customization, quest variety, exploration, dispatch, seasonal events, daily events. Level cap is a long-term milestone, not the only goal.", "unit_progression|94": "A failed quest (defeat or escape) costs 3× that quest\'s Renown reward: Normal −300, Hard −390, Boss −600, Exploration −750. It never drops a Rank: Renown can\'t fall below the start of the current Rank. Applied once per failed quest (loot_progression 90).", "unit_progression|95": "Escaping a battle follows the same reward rules as wipeout: keep kill XP, keep 50% gold, lose all loot, no quest progress. Every escape is still a failed quest and costs the 3× Renown penalty, the same way the old Guild XP penalty applied to every escape.", "unit_progression|97": "Victory: 100% kill XP + 100% gold + all loot committed + quest progress + quest rewards + Renown (if the battle completes a quest) + post-battle 35% recovery.", "unit_progression|98": "Explore expeditions default to 3 linked battles. Rewards granted per battle (gold, loot) via the normal battle+reward pipeline; no Renown per battle. Renown (Exploration 250) is paid once after the 3rd win of the run; a failed run costs −750 once. Per-quest overrides allowed later. Wipeout/escape ends the expedition under locked defeat rules (keep earned XP + 50% gold, lose other loot).", "live_service_features|9": "Parallel systems: Unit XP/leveling, Renown, equipment rarity, loadout customization, item leveling, quest variety, exploration, dispatch, seasonal events, daily events, collection.", "guild_facilities|12": null, "guild_facilities|41": null, "guild_facilities|50": null}, "sb": {"Recruitment Service": {"Reads": "Renown Rank (recruit level: around Rank − 5 to Rank; roster size: base 10 + 1 per 5 Ranks), recruitment costs (economy_framework), roster capacity, region/unlock gates"}, "Guild Service": {"System": "Renown Service", "Owns": "Account-wide Renown and Renown Rank (replaces Guild Level / Guild XP), unlock gating", "Reads": "Successful / failed quests, Renown rules (loot_progression 74-75, 80, 82-83, 87-94), quest level for anti-farming bands (min(Rank, 99) − quest level)", "Writes": "Renown delta, Renown Rank, unlock state", "Primary_Interface": "Awards Renown on a successful quest, applies the 3× fail penalty and the bands, gives Rank and unlocks. Function names would become e.g. AwardRenown / GetRenownRank (the builder decides).", "Failure_Boundary": "Renown never per-kill; only from successful quests; trivial content reduced via unit-XP gap bands; a fail never drops a Rank; no stat/loot effect"}, "Progression Service": {"Must_Not_Own": "Combat damage math, reward/loot generation, Renown (that is Renown Service), equipment stats"}}, "new": [["Guild Progression", "Quest Level", "Quest level = Rank + (difficulty − 3) × 2 ± 1, kept between 1 and 99. Difficulty 1 = Rank − 4, 3 = Rank, 5 = Rank + 4 (±1). Units and gear are still capped at 99 today."], ["Guild Progression", "Anti-farming above Rank 99", "Above Rank 99, the anti-farming gap is measured from min(Rank, 99), so level-99 quests always count as on-level. This is needed or Rank stalls at about 120."], ["Guild Progression", "No Rank Cap", "No Rank cap. Rank keeps going past 99, so higher content can be added later. Units and gear stay capped at 99 (unit_progression 48/87: L99 is the launch cap; racial evolutions L100+ come after launch). Quest level stays between 1 and 99 (loot_progression 87)."], ["Guild Progression", "Failed Quest Penalty", "A failed quest (defeat or escape) costs 3× that quest\'s Renown reward: Normal −300, Hard −390, Boss −600, Exploration −750. It never drops a Rank: Renown can\'t fall below the start of the current Rank. Escape follows the existing round-3 rule (unit_progression 95) for \'counts as a completed battle\'; every escape is still a failed quest and costs the 3× penalty."], ["Guild Progression", "Roster Slots", "+1 roster slot every 5 Ranks, on top of the base 10. Recruits appear around Rank − 5 to Rank. Buildings still cost gold only."], ["Guild Progression", "Roster Over-Cap Saves", "Roster over-cap saves (user ruling 2026-11-10): existing saves keep their extra units. Only new hires and recruits are blocked while over the cap."], ["Guild Progression", "Old Save Conversion", "Old saves: starting Rank = highest unit level − 2 (at least 1). Old Guild XP is dropped, because it was never actually awarded. Happens once, when the save first loads, and is recorded so it never happens again; Renown inside that Rank starts at 0; roster slots already unlocked by the new Rank are given straight away."], ["Guild Progression", "On-Screen Text", "APPROVED as written (USER RULING 2026-11-12 6:17 PM). Name: \\"Renown\\". Steps: Rank (\\"Renown Rank 12\\"). Top of the guild screen: \\"Renown Rank 12\\" with a progress bar \\"1,240 / 1,310 Renown\\". Quest card: \\"+100 Renown\\" (shown lower, e.g. \\"+50 Renown (too easy)\\", when the anti-farming bands reduce it). Victory screen: \\"Quest complete! +100 Renown\\". Defeat / escape screen: \\"The quest failed. −50 Renown\\". Rank-up banner: \\"Your guild\'s renown grows! Renown Rank 12\\", then a list such as \\"+1 roster slot\\", \\"Quests now up to level 16\\", \\"Blacksmith can now upgrade to level 12\\". Blacksmith, when capped by Rank: \\"Your guild needs Renown Rank 13 to upgrade past level 12.\\" Short help text: \\"Renown shows how well-known your guild is. Finish quests to earn it. A higher Rank brings harder quests, better gear upgrades and more room for recruits.\\""]], "S": "LOCKED - USER RULING 2026-11-12 6:17 PM. NOT BUILT.", "BS": " Blacksmith cap (USER RULING 2026-11-12 6:17 PM): the max upgrade level is the lowest of (Rank + 5), Blacksmith building level × 10, and the highest unit\'s level: min(Rank + 5, building × 10, highest unit). The rule that a unit can\'t equip gear above its own level stays."}'

import sqlite3,shutil,json,os,datetime
P=json.loads(PAYLOAD)
d=r'D:\AI\Projects\CTRBLXAI\docs'; b=d+r'\backups'; os.makedirs(b,exist_ok=True)
tag='_before_20261112_renown'
src=sqlite3.connect(d+r'\CTRBLXAI.db'); dst=sqlite3.connect(b+r'\CTRBLXAI'+tag+'.db'); src.backup(dst); dst.close(); src.close()
shutil.copy2(d+r'\CTRBLXAI_Game_Rules.xlsx',b+r'\CTRBLXAI_Game_Rules'+tag+'.xlsx')
shutil.copy2(d+r'\CTRBLXAI_Build_Plan.xlsx',b+r'\CTRBLXAI_Build_Plan'+tag+'.xlsx')
shutil.copy2(d+r'\INDEX.txt',b+r'\INDEX'+tag+'.txt')
c=sqlite3.connect(d+r'\CTRBLXAI.db'); S=P['S']; BS=P['BS']
changed=[]
for k,new in P['upd'].items():
    t,i=k.split('|'); i=int(i)
    rule,notes=c.execute(f'select rule,notes from {t} where id=?',(i,)).fetchone()
    if new is None:
        n2=notes+' | '+S+BS+' (Renown, RULING_renown_20261112.md; pointer: loot_progression 75.)'
        c.execute(f'update {t} set notes=? where id=?',(n2,i))
    else:
        topic=c.execute(f'select topic from {t} where id=?',(i,)).fetchone()[0]
        nt=topic.replace('Guild Level Curve','Renown Rank Curve').replace('Guild Level Cap','Renown Rank Cap').replace('Guild XP penalty','Renown penalty').replace('Guild XP relationship','Renown relationship').replace('Guild Level','Renown Rank').replace('Guild XP','Renown')
        n2=notes+' | '+S+' [Superseded 2026-11-12 6:17 PM: '+('topic: '+topic+'; ' if nt!=topic else '')+'rule: '+rule+']'
        c.execute(f'update {t} set topic=?,rule=?,notes=? where id=?',(nt,new,n2,i))
    changed.append((t,i))
cols=[r[1] for r in c.execute('pragma table_info(service_boundaries)')]
for sysn,f in P['sb'].items():
    row=dict(zip(cols,c.execute('select * from service_boundaries where System=?',(sysn,)).fetchone()))
    old='; '.join(f'{k}: {row[k]}' for k in f)
    sets={**f}
    # store status/superseded in Failure_Boundary tail (no notes column)
    fb=sets.get('Failure_Boundary',row['Failure_Boundary'])
    sets['Failure_Boundary']=fb+' | '+S+' [Superseded 2026-11-12 6:17 PM: '+old+']'
    c.execute('update service_boundaries set '+','.join(f'{k}=?' for k in sets)+' where System=?',(*sets.values(),sysn))
    changed.append(('service_boundaries',sets.get('System',sysn)))
newids=[]
for sec,top,rule in P['new']:
    note=S+' Source: RULING_renown_20261112.md (USER RULING 2026-11-12 6:17 PM) + PROPOSAL_renown_20261112.md.'
    if top=='On-Screen Text': note+=' FLAG for user (recorded as approved, not changed): the defeat-screen text says "−50 Renown" (written for the old −50 draft) but the locked fail penalty is 3× the reward (−300 for Normal); and the Blacksmith text assumes the cap is Rank, while the locked cap is Rank + 5.'
    if top=='No Rank Cap': note+=' Checked against unit_progression 48/87/88: consistent - Rank has no cap, units and gear stay capped at 99.'
    cur=c.execute('insert into loot_progression(section,topic,rule,notes) values(?,?,?,?)',(sec,top,rule,note)); newids.append(cur.lastrowid)
r62=c.execute('select notes from unit_progression where id=62').fetchone()[0]
c.execute('update unit_progression set notes=? where id=62',(r62+' | '+S+' Note: Quest Recommended Level now comes from Renown Rank: quest level = Rank + (difficulty − 3) × 2 ± 1, kept between 1 and 99 (loot_progression '+str(newids[0])+'). Rule unchanged.',))
changed.append(('unit_progression',62))
c.commit(); print(c.execute('pragma integrity_check').fetchone())
print(changed,newids)
